        override fun callback(`uniffiHandle`: Long,`stage`: RustBuffer.ByValue,`bytesLeft`: Long,`eventsSynced`: Int,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeSyncProgressListener.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onProgress`(
